import{_ as e,o as t,c as r,a2 as l}from"./chunks/framework.CCCdsIgc.js";const p=JSON.parse('{"title":"电脑操作","description":"","frontmatter":{},"headers":[],"relativePath":"guide/computer-use.md","filePath":"guide/computer-use.md"}'),i={name:"guide/computer-use.md"};function o(n,a,s,d,u,h){return t(),r("div",null,[...a[0]||(a[0]=[l('<h1 id="电脑操作" tabindex="-1">电脑操作 <a class="header-anchor" href="#电脑操作" aria-label="Permalink to &quot;电脑操作&quot;">​</a></h1><p>有些系统没有网页版、也没有接口，只能在 Windows 程序里点（比如老的 ERP、WMS 客户端）。IT 打开「电脑操作」后，AI 可以替你在这些程序里查询、填写、翻页。</p><h2 id="能做什么" tabindex="-1">能做什么 <a class="header-anchor" href="#能做什么" aria-label="Permalink to &quot;能做什么&quot;">​</a></h2><p>在<strong>办事</strong>模式里直接说，比如：</p><ul><li>「在 ERP 里查一下物料 A01 的库存」</li><li>「把这张表里的 5 条入库记录填进 WMS 的入库单，先别保存，我看一眼」</li><li>「在 ERP 的销售订单列表里翻到最后一页，告诉我最新的 10 单」</li></ul><p>AI 会先找到程序窗口，读出里面的按钮、输入框、表格，再一步一步操作，每一步都把看到的界面写进对话里。</p><h2 id="用之前" tabindex="-1">用之前 <a class="header-anchor" href="#用之前" aria-label="Permalink to &quot;用之前&quot;">​</a></h2><ul><li>先把程序<strong>打开并登录好</strong>。密码、验证码 AI 不代填，需要登录时它会停下来请你自己输入；</li><li>只能操作 IT 允许的程序，命令行、资源管理器、浏览器、远程桌面这些永远不行（网页请用 AI 浏览器）；</li><li>AI 操作时<strong>屏幕顶部会出现蓝色提示条</strong>，这时先别动鼠标和键盘，免得打乱它。</li></ul><h2 id="什么时候会问你" tabindex="-1">什么时候会问你 <a class="header-anchor" href="#什么时候会问你" aria-label="Permalink to &quot;什么时候会问你&quot;">​</a></h2><ul><li>点「保存」「提交」「审核」「删除」「入库」这类按钮，按回车、Ctrl+S、Delete：<strong>每次都问</strong>；</li><li>填身份证号、银行卡号：先问；</li><li>IT 默认打开了「每一步都先确认」，这时普通的点击、填写也会先问你。用熟了可以请 IT 关掉；</li><li>「仅可查看」权限下，AI 只能看、翻页，不能填写和提交。</li></ul><p>这些确认都不能设成「以后自动」。</p><h2 id="随时停下" tabindex="-1">随时停下 <a class="header-anchor" href="#随时停下" aria-label="Permalink to &quot;随时停下&quot;">​</a></h2><p>点提示条上的「<strong>停止</strong>」，任务马上停下。也可以像平时一样在对话里点停止。</p><h2 id="做不了的情况" tabindex="-1">做不了的情况 <a class="header-anchor" href="#做不了的情况" aria-label="Permalink to &quot;做不了的情况&quot;">​</a></h2><p>有些程序用的是自己画的界面（或者是远程桌面里的程序），AI 读不到里面的控件，会直接告诉你。这类程序请找 IT 看有没有接口或网页版。</p>',15)])])}const _=e(i,[["render",o]]);export{p as __pageData,_ as default};
